create temporary view dim_${grass_region_without_quote} as
select
    user_id
    ,item_click_level
    ,dd_click_level
from srdi_mart.dim_sr_data_warehouse_user_label
where grass_region = ${grass_region} and local_date = ${local_date}

--sql_divide_splitter--

create temporary view user_data_${grass_region_without_quote} as
select
    platform
    ,major_app_version
    ,app_version
    ,user_id
    ,max(is_dau_data) as is_dau_data
    ,sum(omni_imp_cnt) as omni_imp_cnt
    ,sum(ppv_cnt) as ppv_cnt
    ,sum(order_cnt) as order_cnt
from
(
    select
        nvl(platform, '') as platform
        ,nvl(regexp_extract(app_version, '(.+)(\\.)(.+)', 1), '') as major_app_version
        ,nvl(app_version, '') as app_version
        ,userid as user_id
        ,1 as is_dau_data
        ,null as omni_imp_cnt
        ,null as ppv_cnt
        ,null as order_cnt
    from traffic.shopee_traffic_dwd_event_stream_hi__reg_s1_live
    where grass_region = ${grass_region}
        and local_date = ${local_date}
        and operation in ('view', 'auto_view')
        and userid > 0

    union all

    select
        nvl(platform, '') as platform
        ,nvl(regexp_extract(app_version, '(.+)(\\.)(.+)', 1), '') as major_app_version
        ,nvl(app_version, '') as app_version
        ,user_id
        ,0 as is_dau_data
        ,if(operation='omni_impression', operation_cnt, 0) as omni_imp_cnt
        ,if(operation='ppv' and is_back=FALSE, operation_cnt, 0) as ppv_cnt
        ,if(operation='order', operation_cnt, 0) as order_cnt
    from srdi_mart.dwd_sr_data_warehouse_platform
    where grass_region = ${grass_region}
        and local_date = ${local_date}
        and operation in ('omni_impression', 'ppv', 'order')
        and user_id > 0
)
group by platform, app_version, major_app_version, user_id

--sql_divide_splitter--

cache table base_data_${grass_region_without_quote} options ('storageLevel' 'MEMORY_AND_DISK_SER') as
select
    platform
    ,nvl(item_click_level, '') as item_click_level
    ,nvl(dd_click_level, '') as dd_click_level
    ,major_app_version
    ,app_version
    ,if(user.is_dau_data>0, user.user_id, null) as user_id
    ,omni_imp_cnt
    ,ppv_cnt
    ,order_cnt
from user_data_${grass_region_without_quote} user
left join dim_${grass_region_without_quote} dim
on user.user_id = dim.user_id

--sql_divide_splitter--

cache table cube_data_${grass_region_without_quote} options ('storageLevel' 'MEMORY_AND_DISK_SER') as
--sql_template_spliter--
select
    major_app_version
    ,app_version
    ,user_id
    ,${fields_placeholder}
    ,sum(omni_imp_cnt) as omni_imp_cnt
    ,sum(ppv_cnt) as ppv_cnt
    ,sum(order_cnt) as order_cnt
from base_data_${grass_region_without_quote}
group by major_app_version,app_version,user_id ${groupby_placeholder}  -- cube with platform,item_click_level,dd_click_level
--sql_template_spliter--

--sql_divide_splitter--

insert overwrite table ${schema}.dws_sr_data_warehouse_platform_user_attribute_level_1d
partition(grass_region=${grass_region}, local_date=${local_date})
select
    platform
    ,item_click_level
    ,dd_click_level
    ,nvl(major_app_version, '__ALL__') as major_app_version
    ,nvl(app_version, '__ALL__') as app_version
    ,count(distinct user_id) as dau
    ,sum(omni_imp_cnt) as omni_imp_cnt
    ,sum(ppv_cnt) as ppv_cnt
    ,sum(order_cnt) as order_cnt
from cube_data_${grass_region_without_quote}
group by platform,item_click_level,dd_click_level,major_app_version,app_version
-- roll up with major_app_version,app_version
grouping sets(
    (platform, item_click_level, dd_click_level)
    ,(major_app_version, platform, item_click_level, dd_click_level)
    ,(major_app_version, app_version, platform, item_click_level, dd_click_level)
)
